#!/usr/bin/env bash
# example-link-check-test.sh — Tests for examples/link-check/scripts/post-link-check.sh
#
# The example agent under examples/ is generated by `fullsend agent new` and
# is meant to be copied, so its post-script has to hold up to the same
# scrutiny as a fleet one: it consumes untrusted model output and turns it
# into a comment on a work item.
#
# Run from the repo root:
#   bash scripts/example-link-check-test.sh

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
POST_SCRIPT="${REPO_ROOT}/examples/link-check/scripts/post-link-check.sh"

FAILURES=0

# Every scratch directory lives under one root that is removed on exit, so an
# early failure under set -e leaves nothing behind.
TEST_TMP="$(mktemp -d)"
trap 'rm -rf "${TEST_TMP}"' EXIT

pass() { echo "PASS: $1"; }
fail() { echo "FAIL: $1 — $2"; FAILURES=$((FAILURES + 1)); }

# run_post <result-json> [env assignments...]
# Runs the post-script the way fullsend runs it: the working directory is the
# RUN directory and the agent's output lives in iteration-<N>/output/, per
# `postCmd.Dir = runDir` in internal/cli/run.go. Always in dry-run mode, so
# nothing is ever posted.
run_post() {
  local result_json="$1"; shift
  local workdir
  workdir="$(mktemp -d "${TEST_TMP}/t.XXXXXX")"
  mkdir -p "${workdir}/iteration-1/output"
  printf '%s' "${result_json}" > "${workdir}/iteration-1/output/agent-result.json"

  local rc=0
  ( cd "${workdir}" \
      && ISSUE_URL="${ISSUE_URL_OVERRIDE:-https://github.com/fullsend-ai/demo/pull/99}" \
         GH_TOKEN="test-token" \
         POST_LINK_CHECK_DRY_RUN=1 \
         env "$@" bash "${POST_SCRIPT}" ) > "${workdir}/stdout" 2> "${workdir}/stderr" || rc=$?
  LAST_STDOUT="$(cat "${workdir}/stdout")"
  LAST_STDERR="$(cat "${workdir}/stderr")"
  rm -rf "${workdir}"
  return "${rc}"
}

# run_post_live <result-json> [old-cli]
# Like run_post but WITHOUT dry run, with a stub `fullsend` first on PATH that
# records its arguments instead of talking to a forge. This is the only way to
# see what the script does on the path that actually posts. The stub answers
# `--help` the way the real CLI does, listing --only-if-exists — or, with the
# optional "old-cli" argument, NOT listing it and failing on any post, which
# is what a runner pinned to a fullsend release older than the generator does.
# With "broken-cli:<rc>" the stub's --help itself exits <rc> (127 stands in
# for a fullsend that is not installed), and any post is recorded.
# With "failing-cli" the stub lists the flag but every post exits non-zero,
# as post-comment does when it cannot resolve the login it posts as.
# LIVE_ISSUE_URL overrides the work item (default: pull request 99 in
# fullsend-ai/demo).
run_post_live() {
  local result_json="$1"; local cli="${2:-new-cli}"
  local workdir stubdir
  workdir="$(mktemp -d "${TEST_TMP}/t.XXXXXX")"; stubdir="$(mktemp -d "${TEST_TMP}/t.XXXXXX")"
  mkdir -p "${workdir}/iteration-1/output"
  printf '%s' "${result_json}" > "${workdir}/iteration-1/output/agent-result.json"
  if [[ "${cli}" == broken-cli:* ]]; then
    printf '#!/usr/bin/env bash\nif [[ "$*" == *--help* ]]; then echo "fullsend: broken" >&2; exit %s; fi\nprintf "%%s\\n" "$@" > "%s/args"\ncat > /dev/null\n' "${cli#broken-cli:}" "${stubdir}" > "${stubdir}/fullsend"
  elif [[ "${cli}" == "failing-cli" ]]; then
    printf '#!/usr/bin/env bash\nif [[ "$*" == *--help* ]]; then echo "  --only-if-exists   update an existing comment but never create one"; exit 0; fi\nprintf "%%s\\n" "$@" > "%s/args"\ncat > /dev/null\necho "Error: cannot resolve the authenticated login" >&2; exit 1\n' "${stubdir}" > "${stubdir}/fullsend"
  elif [[ "${cli}" == "old-cli" ]]; then
    printf '#!/usr/bin/env bash\nif [[ "$*" == *--help* ]]; then echo "  --dry-run   print what would be posted"; exit 0; fi\nprintf "%%s\\n" "$@" > "%s/args"\necho "Error: unknown flag: --only-if-exists" >&2; exit 1\n' "${stubdir}" > "${stubdir}/fullsend"
  else
    printf '#!/usr/bin/env bash\nif [[ "$*" == *--help* ]]; then echo "  --only-if-exists   update an existing comment but never create one"; exit 0; fi\nprintf "%%s\\n" "$@" > "%s/args"\ncat > "%s/stdin"\n' "${stubdir}" "${stubdir}" > "${stubdir}/fullsend"
  fi
  chmod +x "${stubdir}/fullsend"
  local rc=0
  ( cd "${workdir}" \
      && PATH="${stubdir}:${PATH}" \
         ISSUE_URL="${LIVE_ISSUE_URL:-https://github.com/fullsend-ai/demo/pull/99}" \
         GH_TOKEN="test..." \
         bash "${POST_SCRIPT}" ) > "${workdir}/stdout" 2> "${workdir}/stderr" || rc=$?
  LAST_STDOUT="$(cat "${workdir}/stdout")"
  LAST_STDERR="$(cat "${workdir}/stderr")"
  LAST_FULLSEND_ARGS="$(cat "${stubdir}/args" 2>/dev/null || true)"
  LAST_FULLSEND_STDIN="$(cat "${stubdir}/stdin" 2>/dev/null || true)"
  rm -rf "${workdir}" "${stubdir}"
  return "${rc}"
}

# --- No unfilled generator markers anywhere under examples/ ---
#
# skillsaw's content-placeholder-text rule catches TODO and bracket
# placeholders but NOT the `<!-- FILL IN: ... -->` marker `fullsend agent new`
# actually emits — verified by appending one and watching `make lint` pass.
# This is the check that makes the README's claim true.
# Scoped to agent definitions: those are the files the generator writes
# markers into. examples/README.md names the marker in prose, on purpose.
_marked=$(grep -rln "FILL IN" "${REPO_ROOT}"/examples/*/agents/*.md 2>/dev/null || true)
if [[ -n "${_marked}" ]]; then
  fail "no-unfilled-markers" "unfilled FILL IN marker(s) in: ${_marked}"
else
  pass "no-unfilled-markers"
fi

# --- The script exists and is executable ---

if [[ -x "${POST_SCRIPT}" ]]; then
  pass "post-script-is-executable"
else
  fail "post-script-is-executable" "${POST_SCRIPT} is missing or not executable"
fi

# --- Happy path: findings are posted ---

if run_post '{"status":"findings","summary":"2 broken links","comment":"- a.md -> missing.md"}'; then
  if [[ "${LAST_STDOUT}" == *"2 broken links"* && "${LAST_STDOUT}" == *"a.md"* ]]; then
    pass "findings-are-rendered"
  else
    fail "findings-are-rendered" "summary or comment missing from output: ${LAST_STDOUT}"
  fi
else
  fail "findings-are-rendered" "script exited non-zero"
fi

# --- The dry-run preview cannot issue workflow commands ---
#
# Under GitHub Actions a stdout line starting with "::" is a workflow command.
# The preview prints model output, so it must sit inside a stop-commands block
# opened and closed by the same unguessable token, with the model's own "::"
# lines strictly inside it.

if run_post '{"status":"findings","summary":"1 broken link","comment":"::warning::forged\n- a.md -> b.md"}'; then
  _first="$(printf '%s\n' "${LAST_STDOUT}" | head -n 1)"
  _last="$(printf '%s\n' "${LAST_STDOUT}" | tail -n 1)"
  _tok="${_first#::stop-commands::}"
  if [[ "${_first}" =~ ^::stop-commands::[0-9a-f]{32}$ && "${_last}" == "::${_tok}::" \
        && "$(printf '%s\n' "${LAST_STDOUT}" | sed '1d;$d')" == *"::warning::forged"* ]]; then
    pass "dry-run-preview-is-inside-stop-commands"
  else
    fail "dry-run-preview-is-inside-stop-commands" "unexpected framing: ${LAST_STDOUT}"
  fi
else
  fail "dry-run-preview-is-inside-stop-commands" "script exited non-zero: ${LAST_STDERR}"
fi

# --- status ok under dry run posts nothing ---

if run_post '{"status":"ok","summary":"all good","comment":"All documentation links resolve."}'; then
  if [[ "${LAST_STDERR}" == *"nothing to post"* ]]; then
    pass "ok-status-dry-run-posts-nothing"
  else
    fail "ok-status-dry-run-posts-nothing" "expected a 'nothing to post' notice, got: ${LAST_STDERR}"
  fi
else
  fail "ok-status-dry-run-posts-nothing" "script exited non-zero"
fi

# The arguments every live post must carry: the repository and number parsed
# from ISSUE_URL, and the marker that lets post-comment edit the earlier
# comment instead of adding a second one.
EXPECTED_TARGET_ARGS=$'issues\npost-comment\n--tracker\ngithub\n--project\nfullsend-ai/demo\n--number\n99\n--marker\n<!-- fullsend:link-check-agent -->\n'

# --- status ok on the live path replaces an earlier findings comment ---
#
# The decision "is there an earlier comment to replace" belongs to
# `fullsend issues post-comment --only-if-exists`, which finds the marked
# comment through the forge client. The script must delegate, not reimplement.

if run_post_live '{"status":"ok","summary":"all good","comment":"All documentation links resolve."}'; then
  if [[ "${LAST_FULLSEND_ARGS}" == *$'issues\npost-comment\n'* && "${LAST_FULLSEND_ARGS}" == *$'--only-if-exists\n'* && "${LAST_FULLSEND_ARGS}" == *$'--marker\n'* ]]; then
    pass "ok-status-live-delegates-only-if-exists"
  else
    fail "ok-status-live-delegates-only-if-exists" "expected fullsend issues post-comment --only-if-exists, got args: ${LAST_FULLSEND_ARGS}"
  fi
  if [[ "${LAST_FULLSEND_ARGS}" == "${EXPECTED_TARGET_ARGS}"$'--only-if-exists\n--keep-history=false\n--result\n-' ]]; then
    pass "ok-status-live-targets-the-work-item"
  else
    fail "ok-status-live-targets-the-work-item" "got args: ${LAST_FULLSEND_ARGS}"
  fi
  if [[ "${LAST_FULLSEND_STDIN}" == *"All documentation links resolve."* ]]; then
    pass "ok-status-live-sends-the-all-clear-body"
  else
    fail "ok-status-live-sends-the-all-clear-body" "all-clear body not piped to fullsend: ${LAST_FULLSEND_STDIN}"
  fi
else
  fail "ok-status-live-delegates-only-if-exists" "script exited non-zero: ${LAST_STDERR}"
fi

# --- status ok on a runner whose fullsend predates --only-if-exists ---
#
# The runner's fullsend is pinned by the repository, not by the CLI that
# generated this script. On an older CLI the ok path must fall back to the
# previous behaviour — post nothing — and never call a flag it does not have.

if run_post_live '{"status":"ok","summary":"all good","comment":"All documentation links resolve."}' old-cli; then
  if [[ "${LAST_STDERR}" == *"nothing to post"* && -z "${LAST_FULLSEND_ARGS}" ]]; then
    pass "ok-status-live-older-fullsend-posts-nothing"
  else
    fail "ok-status-live-older-fullsend-posts-nothing" "expected a nothing-to-post notice and no post call; stderr: ${LAST_STDERR}; args: ${LAST_FULLSEND_ARGS}"
  fi
else
  fail "ok-status-live-older-fullsend-posts-nothing" "script exited non-zero on an older fullsend: ${LAST_STDERR}"
fi

# --- status ok with a fullsend whose --help fails ---
#
# A missing or broken fullsend is a broken runner, not an older CLI: the run
# must fail, naming the --help failure, rather than skip the replacement as
# if the flag were merely absent.

for _rc in 1 127; do
  if run_post_live '{"status":"ok","summary":"all good","comment":"All documentation links resolve."}' "broken-cli:${_rc}"; then
    fail "ok-status-live-broken-help-fails-the-run-rc${_rc}" "script exited 0 although --help failed"
  elif [[ "${LAST_STDERR}" == *"--help' failed"* && -z "${LAST_FULLSEND_ARGS}" ]]; then
    pass "ok-status-live-broken-help-fails-the-run-rc${_rc}"
  else
    fail "ok-status-live-broken-help-fails-the-run-rc${_rc}" "expected a --help failure and no post; stderr: ${LAST_STDERR}; args: ${LAST_FULLSEND_ARGS}"
  fi
done

# --- status findings on the live path posts unconditionally ---

if run_post_live '{"status":"findings","summary":"1 broken link","comment":"- `docs/a.md:3` -> `../x.md`"}'; then
  if [[ "${LAST_FULLSEND_ARGS}" == *$'issues\npost-comment\n'* && "${LAST_FULLSEND_ARGS}" != *"--only-if-exists"* ]]; then
    pass "findings-live-posts-without-only-if-exists"
  else
    fail "findings-live-posts-without-only-if-exists" "got args: ${LAST_FULLSEND_ARGS}"
  fi
  if [[ "${LAST_FULLSEND_ARGS}" == "${EXPECTED_TARGET_ARGS}"$'--result\n-' ]]; then
    pass "findings-live-targets-the-work-item"
  else
    fail "findings-live-targets-the-work-item" "got args: ${LAST_FULLSEND_ARGS}"
  fi
  if [[ "${LAST_FULLSEND_STDIN}" == $'**1 broken link**\n\n- `docs/a.md:3` -> `../x.md`' ]]; then
    pass "findings-live-sends-summary-and-comment"
  else
    fail "findings-live-sends-summary-and-comment" "unexpected body on stdin: ${LAST_FULLSEND_STDIN}"
  fi
else
  fail "findings-live-posts-without-only-if-exists" "script exited non-zero: ${LAST_STDERR}"
fi

# --- A failed post fails the run ---
#
# post-comment exits non-zero without posting when it cannot resolve its own
# login. The script must surface that (set -e), on both paths, rather than
# report success with nothing posted.

for _status in ok findings; do
  if run_post_live "{\"status\":\"${_status}\",\"summary\":\"s\",\"comment\":\"c\"}" failing-cli; then
    fail "${_status}-live-post-failure-fails-the-run" "script exited 0 although post-comment failed"
  elif [[ "${LAST_FULLSEND_ARGS}" == *$'issues\npost-comment\n'* ]]; then
    pass "${_status}-live-post-failure-fails-the-run"
  else
    fail "${_status}-live-post-failure-fails-the-run" "script failed before posting: ${LAST_STDERR}"
  fi
done

# --- An issue URL is a valid work item too ---

if LIVE_ISSUE_URL="https://github.com/o/r/issues/7" \
    run_post_live '{"status":"findings","summary":"1 broken link","comment":"- x"}'; then
  if [[ "${LAST_FULLSEND_ARGS}" == *$'--project\no/r\n--number\n7\n'* ]]; then
    pass "issue-url-targets-the-issue"
  else
    fail "issue-url-targets-the-issue" "got args: ${LAST_FULLSEND_ARGS}"
  fi
else
  fail "issue-url-targets-the-issue" "script exited non-zero: ${LAST_STDERR}"
fi

# --- Rejected inputs: each must fail rather than post ---

assert_rejected() {
  local name="$1" json="$2" expect="$3"
  if run_post "${json}"; then
    fail "${name}" "script accepted input it should reject"
  elif [[ "${LAST_STDERR}" == *"${expect}"* ]]; then
    pass "${name}"
  else
    fail "${name}" "wrong error; wanted '${expect}', got: ${LAST_STDERR}"
  fi
}

assert_rejected "rejects-invalid-json" 'not json at all' "is not a JSON object"
# `jq -e .` used to be the gate: it reports a bare null/false document as
# invalid JSON, and lets a top-level array through to a raw jq error under
# set -e. All three must now be refused as "not a JSON object".
assert_rejected "rejects-bare-null" 'null' "is not a JSON object"
assert_rejected "rejects-bare-false" 'false' "is not a JSON object"
assert_rejected "rejects-top-level-array" '[{"status":"ok"}]' "is not a JSON object"
assert_rejected "rejects-multiline-summary" \
  '{"status":"findings","summary":"line one\nline two","comment":"c"}' \
  "summary must be a single line"
assert_rejected "rejects-unknown-status" '{"status":"explode","summary":"s","comment":"c"}' "status must be"
assert_rejected "rejects-missing-summary" '{"status":"findings","comment":"c"}' "summary is required"
assert_rejected "rejects-missing-comment" '{"status":"findings","summary":"s"}' "comment is required"

# A non-string field must be ignored by the allowlist, not coerced. jq's
# type guard turns it into an empty value, which then fails the required check.
assert_rejected "rejects-non-string-summary" \
  '{"status":"findings","summary":{"nested":true},"comment":"c"}' "summary is required"
assert_rejected "rejects-non-string-status" \
  '{"status":["findings"],"summary":"s","comment":"c"}' "status must be"

# Over-long summary is refused rather than silently truncated.
LONG_SUMMARY="$(printf 'x%.0s' $(seq 1 201))"
assert_rejected "rejects-over-long-summary" \
  "{\"status\":\"findings\",\"summary\":\"${LONG_SUMMARY}\",\"comment\":\"c\"}" \
  "summary exceeds"

# --- ISSUE_URL is validated, not trusted ---

for bad_url in \
  "https://evil.example.com/fullsend-ai/demo/pull/99" \
  "https://github.com/fullsend-ai/demo/pull/99/../../x" \
  "not-a-url"
do
  ISSUE_URL_OVERRIDE="${bad_url}" \
    assert_rejected "rejects-issue-url:${bad_url}" \
      '{"status":"findings","summary":"s","comment":"c"}' \
      "not a GitHub issue or pull request URL"
done
unset ISSUE_URL_OVERRIDE

# --- An over-long comment is truncated, not rejected ---

LONG_COMMENT="$(printf 'y%.0s' $(seq 1 17000))"
if run_post "{\"status\":\"findings\",\"summary\":\"s\",\"comment\":\"${LONG_COMMENT}\"}"; then
  if [[ "${LAST_STDOUT}" == *"(truncated)"* ]]; then
    pass "truncates-over-long-comment"
  else
    fail "truncates-over-long-comment" "expected a truncation marker"
  fi
  # The marker must fit INSIDE the cap, not extend past it: cutting at
  # MAX_COMMENT_CHARS and then appending would overshoot the limit the
  # result schema declares.
  # Preview layout: ::stop-commands::<token>, **summary**, a blank line, the
  # comment, ::<token>:: — keep only the comment.
  body_len=$(printf '%s\n' "${LAST_STDOUT}" | sed '1,3d;$d' | wc -c | tr -d ' ')
  body_len=$(( body_len - 1 ))   # the comment's own trailing newline
  if (( body_len <= 16384 )); then
    pass "truncated-comment-stays-within-the-cap"
  else
    fail "truncated-comment-stays-within-the-cap" "comment body is ${body_len} chars, cap is 16384"
  fi
else
  fail "truncates-over-long-comment" "script exited non-zero"
fi

# --- Missing result file ---

workdir="$(mktemp -d "${TEST_TMP}/t.XXXXXX")"
rc=0
( cd "${workdir}" && ISSUE_URL="https://github.com/fullsend-ai/demo/pull/99" \
    GH_TOKEN=t POST_LINK_CHECK_DRY_RUN=1 bash "${POST_SCRIPT}" ) >/dev/null 2>"${workdir}/err" || rc=$?
if [[ "${rc}" -ne 0 ]] && grep -q "no agent-result.json found" "${workdir}/err"; then
  pass "rejects-missing-result-file"
else
  fail "rejects-missing-result-file" "expected a not-found failure, got: $(cat "${workdir}/err")"
fi
rm -rf "${workdir}"

# --- Later iterations win, and a validated iteration wins over both ---

workdir="$(mktemp -d "${TEST_TMP}/t.XXXXXX")"
for n in 1 2; do
  mkdir -p "${workdir}/iteration-${n}/output"
  printf '{"status":"findings","summary":"iteration %s","comment":"c"}' "${n}" \
    > "${workdir}/iteration-${n}/output/agent-result.json"
done
out=$( cd "${workdir}" && ISSUE_URL="https://github.com/fullsend-ai/demo/pull/99" \
    GH_TOKEN=t POST_LINK_CHECK_DRY_RUN=1 bash "${POST_SCRIPT}" 2>/dev/null )
if [[ "${out}" == *"iteration 2"* ]]; then
  pass "uses-the-last-iteration"
else
  fail "uses-the-last-iteration" "expected iteration 2, got: ${out}"
fi

# FULLSEND_VALIDATED_ITERATION_DIR names the iteration that passed validation,
# which is not necessarily the last one, so it must win over the scan.
out=$( cd "${workdir}" && ISSUE_URL="https://github.com/fullsend-ai/demo/pull/99" \
    GH_TOKEN=t POST_LINK_CHECK_DRY_RUN=1 \
    FULLSEND_VALIDATED_ITERATION_DIR="${workdir}/iteration-1/output" \
    bash "${POST_SCRIPT}" 2>/dev/null )
if [[ "${out}" == *"iteration 1"* ]]; then
  pass "validated-iteration-wins"
else
  fail "validated-iteration-wins" "expected iteration 1, got: ${out}"
fi
rm -rf "${workdir}"

# --- iteration-10 must beat iteration-9 (numeric, not lexical, ordering) ---

workdir="$(mktemp -d "${TEST_TMP}/t.XXXXXX")"
for n in 9 10; do
  mkdir -p "${workdir}/iteration-${n}/output"
  printf '{"status":"findings","summary":"iteration %s","comment":"c"}' "${n}" \
    > "${workdir}/iteration-${n}/output/agent-result.json"
done
out=$( cd "${workdir}" && ISSUE_URL="https://github.com/fullsend-ai/demo/pull/99" \
    GH_TOKEN=t POST_LINK_CHECK_DRY_RUN=1 bash "${POST_SCRIPT}" 2>/dev/null )
if [[ "${out}" == *"iteration 10"* ]]; then
  pass "iteration-10-beats-iteration-9"
else
  fail "iteration-10-beats-iteration-9" "lexical ordering would pick 9; got: ${out}"
fi
rm -rf "${workdir}"

# --- A validated iteration dir with no result is an error, not a fallback ---

workdir="$(mktemp -d "${TEST_TMP}/t.XXXXXX")"
mkdir -p "${workdir}/iteration-1/output" "${workdir}/empty"
printf '{"status":"findings","summary":"s","comment":"c"}' \
  > "${workdir}/iteration-1/output/agent-result.json"
rc=0
( cd "${workdir}" && ISSUE_URL="https://github.com/fullsend-ai/demo/pull/99" \
    GH_TOKEN=t POST_LINK_CHECK_DRY_RUN=1 \
    FULLSEND_VALIDATED_ITERATION_DIR="${workdir}/empty" \
    bash "${POST_SCRIPT}" ) >/dev/null 2>"${workdir}/err" || rc=$?
if [[ "${rc}" -ne 0 ]] && grep -q "no agent-result.json" "${workdir}/err"; then
  pass "validated-dir-without-result-is-an-error"
else
  fail "validated-dir-without-result-is-an-error" "expected a failure, got rc=${rc}"
fi
rm -rf "${workdir}"

# --- status: error still posts (it is a finding the author should see) ---

if run_post '{"status":"error","summary":"could not read the PR","comment":"gh api failed"}'; then
  if [[ "${LAST_STDOUT}" == *"could not read the PR"* ]]; then
    pass "error-status-is-posted"
  else
    fail "error-status-is-posted" "expected the error summary in the output"
  fi
else
  fail "error-status-is-posted" "script exited non-zero"
fi

# --- GH_TOKEN reaches the runner, not the sandbox ---
#
# The github-ro provider declares GH_TOKEN, so OpenShell hands the sandbox a
# placeholder and swaps in the real token on the wire. The post-script runs on
# the runner and needs the real one, so env.runner must keep it. That
# env.sandbox does NOT carry it is checked, with the fleet harnesses, by
# scripts/sandbox-credential-boundary-test.sh.

HARNESS="${REPO_ROOT}/examples/link-check/harness/link-check.yaml"
if [[ "$(yq -r '.env.runner | has("GH_TOKEN")' "${HARNESS}")" == "true" ]]; then
  pass "runner-env-has-gh-token"
else
  fail "runner-env-has-gh-token" "env.runner in ${HARNESS} lost GH_TOKEN, which the post-script needs"
fi

# --- Required environment: GH_TOKEN and ISSUE_URL ---
#
# The result is otherwise valid and the run is a dry run, so the only thing
# that can stop it is the missing variable — checked by its own message.

for _var in GH_TOKEN ISSUE_URL; do
  _name="requires-$(tr '[:upper:]_' '[:lower:]-' <<<"${_var}")"
  workdir="$(mktemp -d "${TEST_TMP}/t.XXXXXX")"
  mkdir -p "${workdir}/iteration-1/output"
  echo '{"status":"findings","summary":"1 broken link","comment":"- x"}' \
    > "${workdir}/iteration-1/output/agent-result.json"
  rc=0
  ( cd "${workdir}" && env GH_TOKEN=t ISSUE_URL="https://github.com/fullsend-ai/demo/pull/99" \
      POST_LINK_CHECK_DRY_RUN=1 env -u "${_var}" bash "${POST_SCRIPT}" ) \
      >/dev/null 2>"${workdir}/err" || rc=$?
  if [[ "${rc}" -ne 0 ]] && grep -qF "${_var} must be set" "${workdir}/err"; then
    pass "${_name}"
  else
    fail "${_name}" "expected a failure naming ${_var}; rc=${rc}, stderr: $(cat "${workdir}/err")"
  fi
  rm -rf "${workdir}"
done

if [[ "${FAILURES}" -gt 0 ]]; then
  echo "${FAILURES} test(s) failed"
  exit 1
fi
echo "All tests passed"
